import options from '../options';
import { vnodeReconciler } from './index';

/**
 * Proxy an event to hooked event handlers
 * @param {Event} e The event object from the browser
 * @private
 */
export function eventProxy(e) {
	this._listeners[e.type + false](options.event ? options.event(e) : e);
}

export function eventProxyCapture(e) {
	this._listeners[e.type + true](options.event ? options.event(e) : e);
}

export function invokeDiffHook(vnode) {
	if (options._diff) options._diff(vnode);
}

export function invokeRenderHook(vnode) {
	if (options._render) options._render(vnode);
}

export function invokeDiffedHook(vnode) {
	if (options.diffed) options.diffed(vnode);
}

export function invokeCommitHook(vnode, commitQueue) {
	if (options._commit) options._commit(vnode, commitQueue);
}

export function invokeUnmountHook(vnode) {
	if (options.unmount) options.unmount(vnode);
}

export function invokeCatchError(error, vnode, oldVNode) {
	options._catchError(error, vnode, oldVNode);
}

export function invokeRootHook(vnode, parentDom) {
	if (options._root) options._root(vnode, parentDom);
}

export function invokeVnodeHook(vnode) {
	if (options.vnode) options.vnode(vnode);
}

export function getDebounceRendering() {
	return options.debounceRendering;
}

export function diffProps(dom, newProps, oldProps, isSvg, hydrate) {
	return vnodeReconciler.diffProps(dom, newProps, oldProps, isSvg, hydrate);
}

export function setProperty(dom, name, value, oldValue, isSvg) {
	return vnodeReconciler.applyNamedProperty(dom, name, value, oldValue, isSvg);
}

